"""Host checks run actual money event/projection code, not an Android database. Device output is mandatory separately."""
from pathlib import Path
import os, re, subprocess, tempfile, shutil
ROOT=Path(__file__).resolve().parents[1]
LABELS=('stable_ids_zero_missing_archive_and_immutable_import','checked_first_edit_cross_month_and_stale_refusal','void_not_zero_and_one_step_targeted_undo','late_failure_and_unrelated_write_roll_back','schedules_and_original_batch_history_preserved','reopen_restore_exact_and_independent_media','malformed_histories_refused_original_replay_intact')
def required(api):return [f'AMEND_SCOPE api={api} package=com.supercubegame.pockettodo.v12.preview hardware=ranchu isolated=true',*['AMEND_NATIVE '+s+' PASS' for s in LABELS],'DEVICE_DATABASE_RESULT ledger_changes 2/2 PASS','INSTRUMENTATION_CODE: -1']
def parse(text,api):
    lines=[s.removeprefix('INSTRUMENTATION_RESULT: stream=') for s in text.splitlines()];got=[s for s in lines if s.startswith(('AMEND_','DEVICE_DATABASE_RESULT','INSTRUMENTATION_CODE:'))]
    if api not in (26,34) or got!=required(api) or re.search(r'DEVICE_DATABASE_FAILED|INSTRUMENTATION_(?:FAILED|ABORTED)|AssertionError|Exception:|Process crashed',text):raise AssertionError('Ledger changes not verified; see device-ledger-changes.txt')
